/* Unified 120×50 designer: one outer box 8.2×3.8 cm with two 2×2.5 cm print boxes inside */
.barcode-dual-outer-frame {
    display: none;
    position: relative;
    box-sizing: border-box;
    margin: 0 auto;
    padding: 0 48px 36px 0;
    pointer-events: auto;
}
.dual-barcode-layout.barcode-dual-unified-120x50 .barcode-dual-outer-frame {
    display: block;
}
.barcode-dual-outer-frame {
    border: 1px solid #1e293b;
    background: #fff;
}
.barcode-dual-outer-frame::before {
    content: '';
    position: absolute;
    left: 0;
    right: 48px;
    top: 50%;
    height: 0;
    border-top: 1px dashed rgba(148, 163, 184, 0.55);
    pointer-events: none;
    z-index: 1;
}
.barcode-dual-outer-frame::after {
    content: '';
    position: absolute;
    top: 0;
    bottom: 36px;
    left: 50%;
    width: 0;
    border-left: 1px dashed rgba(148, 163, 184, 0.45);
    pointer-events: none;
    z-index: 1;
}
.barcode-dual-outer-ruler-w,
.barcode-dual-outer-ruler-h {
    position: absolute;
    color: #16a34a;
    font-size: 12px;
    font-weight: 700;
    pointer-events: none;
    z-index: 3;
}
.barcode-dual-outer-ruler-w {
    left: 0;
    right: 48px;
    bottom: 8px;
    text-align: center;
}
.barcode-dual-outer-ruler-h {
    right: 6px;
    top: 50%;
    transform: translateY(-50%) rotate(-90deg);
    white-space: nowrap;
}
.barcode-dual-sheet-inner {
    position: relative;
    overflow: hidden;
    transform-origin: top left;
}
.dual-barcode-layout.barcode-dual-unified-120x50 .barcode-dual-sticker-shell {
    display: block;
    position: relative;
    left: auto;
    top: auto;
    right: auto;
    bottom: auto;
    width: auto;
    height: auto;
}
.dual-barcode-layout.barcode-dual-unified-120x50 #barcodeLabelsContainer {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    display: block;
    gap: 0;
}
.dual-barcode-layout.barcode-dual-unified-120x50 .barcode-preview-block {
    position: absolute !important;
    margin: 0;
    padding: 0;
    min-height: 0;
}
.dual-barcode-layout.barcode-dual-unified-120x50 .barcode-default-wrap,
.dual-barcode-layout.barcode-dual-unified-120x50 .barcode-default-inner {
